import Base

type RequestBox<-R: Type> is Type:
  RequestBox{-T: Type, value: T, equation: {T == R : Type}}

def request_unbox(-R: Type, box: RequestBox<R>) -> R:
  match box:
    case RequestBox{T, value, equation}:
      %equation : _
      value

type RequestGroup is Type:
  TextRequest{value: String}
  ArrayRequest{value: Array<String>}
  WideRequest{n0: U32, n1: U32, n2: U32, n3: U32, n4: U32, n5: U32, n6: U32, n7: U32, n8: U32, n9: U32, n10: U32, n11: U32, n12: U32, n13: U32, n14: U32, n15: U32, n16: U32, n17: U32, n18: U32, n19: U32, n20: U32, n21: U32, n22: U32, n23: U32, n24: U32, n25: U32, n26: U32, n27: U32, n28: U32, n29: U32, n30: U32, n31: U32, n32: U32, n33: U32, n34: U32, n35: U32, n36: U32, n37: U32, n38: U32, n39: U32, n40: U32, n41: U32, n42: U32, n43: U32, n44: U32, n45: U32, n46: U32, n47: U32, n48: U32, n49: U32, n50: U32, n51: U32, n52: U32, n53: U32, n54: U32, n55: U32, n56: U32, n57: U32, n58: U32, n59: U32, n60: U32, n61: U32, n62: U32, n63: U32, n64: U32, n65: U32}

type Request is Type:
  GroupRequest{box: RequestBox<RequestGroup>}

def group_result(request: RequestGroup) -> Type:
  match request:
    case TextRequest{_}: String
    case ArrayRequest{_}: Array<String>
    case WideRequest{_, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _}: String

def group_step(request: RequestGroup) -> group_result(request):
  match request:
    case TextRequest{value}: value
    case ArrayRequest{value}: value
    case WideRequest{first, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, last}: U32.show((first + last : U32))

def result(request: Request) -> Type:
  match request:
    case GroupRequest{box}: group_result(request_unbox(RequestGroup, box))

def step(request: Request) -> result(request):
  match request:
    case GroupRequest{box}: group_step(request_unbox(RequestGroup, box))

def print_both(scalar: String, selected: Array<String> & String) -> IO(Unit):
  match selected:
    case Tuple{array, value}: IO.print(String.append(scalar, String.append("|", value)))

def exercise(+text: String) -> IO(Unit):
  scalar = step(GroupRequest{RequestBox{RequestGroup, TextRequest{text}, {==}}})
  array = step(GroupRequest{RequestBox{RequestGroup, ArrayRequest{Array.new(String, 1n, text)}, {==}}})
  print_both(scalar, Array.get(String, array, 0))

def print_argument(args: List<String>) -> IO(Unit):
  match args:
    case _ <> text <> _: exercise(text)
    case _: exercise("empty")

def main() -> IO(Unit):
  IO.bind(List<String>, Unit, IO.args(), print_argument)

